const input = $json.body ?? $json;
const text = String(input.message ?? input.text ?? '').trim();
if (!text) throw new Error('O campo message e obrigatorio.');
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 3 | 8)).toString(16); });
const correlationId = input.correlation_id || uuid();
return [{ json: { correlation_id: correlationId, external_message_id: input.external_message_id || correlationId, channel: String(input.channel || 'webhook'), sender_id: String(input.sender_id || 'demo-user'), requested_client_id: input.client_id ? String(input.client_id) : null, message: text, raw_payload: input, demo_mode: true, live_mode: false } }];
